import{_ as l,l as s,o as a,c,v as t,p as i,x as o,d as n,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const x=JSON.parse('{"title":"读写锁","description":"","frontmatter":{"title":"读写锁","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/rwlock.md","filePath":"cs/rwlock.md","lastUpdated":1789023840000}'),h={name:"cs/rwlock.md"};function _(m,e,u,k,f,E){const r=s("Mermaid");return a(),c("div",null,[e[1]||(e[1]=t('<h1 id="读写锁" tabindex="-1">读写锁 <a class="header-anchor" href="#读写锁" aria-label="Permalink to &quot;读写锁&quot;">​</a></h1><div class="epigraph"><p>读者与读者可以重叠；写者与任何人互斥。读多写少时它比一把 mutex 更松，写者却可能被源源不断的读者挡住。</p><footer>—— 据 Silberschatz et al., Operating System Concepts；Love, LKD 整理</footer></div><p><a href="/cs/futex">上一课</a>让互斥可以很便宜。许多内核结构（路由表、挂载表）读远多于写：读者彼此不破坏不变量。缺口是 <strong>rwlock</strong>：共享读、排他写。本课钉语义与写者饥饿，不把 seqlock、RCU 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>mutex 把读者也串行化，吞吐被锁字卡住。<a href="/cs/race-critical">临界区</a> 的不变量若只被写者打破，读者重叠是安全的。实现：计数「当前读者」或用状态字的读计数+写标志，获取时原子更新。写者等到计数为零。缺口不是 futex 的 wait 机制（可以建在它或自旋上），而是这套<strong>兼容性矩阵</strong>。</p><p><span class="marginnote">写者饥饿：读者不断进场，计数永不归零。对策是写者到达后阻挡新读者，或改用 seqlock/RCU。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>read_lock</code>：若无写者则读者计数加一。<code>write_lock</code>：等无读者无写者。IRQ 版同样要标明能否在硬中断里读。睡眠版 rwsem：等待者可睡，规则同 mutex——禁止 IRQ。公平策略：写者等待时新读者是否允许，本课要求说清楚，默认承认存在饥饿模式。</p>',8)),(a(),i(p,null,{default:o(()=>[d(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20R1%5B%22%E8%AF%BB%E8%80%85%22%5D%20--%3E%20OK%5B%22%E5%8F%AF%E9%87%8D%E5%8F%A0%22%5D%0A%20%20R2%5B%22%E8%AF%BB%E8%80%85%22%5D%20--%3E%20OK%0A%20%20W%5B%22%E5%86%99%E8%80%85%22%5D%20--%3E%20EX%5B%22%E4%B8%8E%E6%89%80%E6%9C%89%E4%BA%BA%E4%BA%92%E6%96%A5%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>升级（持读再要写）易死锁：另一读者同样升级。主干禁止隐式升级。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>rwlock 提高读侧并行，写侧延迟变差。与<a href="/cs/scheduling-metrics">调度</a>：一长串读者会把写者的等待做成饥饿，公平尺子坏掉。缓存上，读计数仍是共享行，读者多时也会乒乓——这把后课 seqlock（读侧几乎不写共享行）和 RCU 的动机钉住。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 Linux <code>rwlock_t</code> 与 <code>rw_semaphore</code> 的全部 API 对照完。也不把数据库里的意向锁混进来。seqlock 用版本号让读者无锁重试，下一课。</p><p>后课默认：读可重叠、写排他，写者可能饿。读侧几乎不写锁字的版本号方案，下一课 seqlock。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>rwlock：读者共享、写者排他；写者可被读者流饿死。</li><li>不可随意读升级为写。</li><li>版本号无锁读是下一课。</li><li>出处：Silberschatz et al., <em>OSC</em>；Love, <em>LKD</em>。</li></ul>',8))])}const q=l(h,[["render",_]]);export{x as __pageData,q as default};
